
import { useState } from 'react';
import { ArrowRightIcon } from '@heroicons/react/24/outline';
import Link from 'next/link';

export default function LoanApplication() {
  const [amount, setAmount] = useState('');
  const [term, setTerm] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    // Handle loan application submission logic here
    console.log('Loan Amount:', amount, 'Term:', term);
  };

  return (
    <div className="flex flex-col p-6">
      <h1 className="text-2xl font-bold">Apply for a Loan</h1>
      <form onSubmit={handleSubmit} className="mt-4">
        <div className="mb-4">
          <label htmlFor="amount" className="block text-sm font-medium text-gray-700">
            Loan Amount
          </label>
          <input
            type="number"
            id="amount"
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
            className="mt-1 block w-full border border-gray-300 rounded-md p-2"
            required
          />
        </div>
        <div className="mb-4">
          <label htmlFor="term" className="block text-sm font-medium text-gray-700">
            Loan Term (months)
          </label>
          <input
            type="number"
            id="term"
            value={term}
            onChange={(e) => setTerm(e.target.value)}
            className="mt-1 block w-full border border-gray-300 rounded-md p-2"
            required
          />
        </div>
        <button
          type="submit"
          className="flex items-center gap-2 rounded-lg bg-blue-500 px-4 py-2 text-white transition-colors hover:bg-blue-400"
        >
          Submit Application <ArrowRightIcon className="w-5" />
        </button>
      </form>
      <Link href="/dashboard" className="mt-4 text-blue-500">
        Back to Dashboard
      </Link>
    </div>
  );
}
